def M_step(X, r, k):
    """
    M-step - Maximization
    Calculate new MU, SIGMA and PI matrices
    based on the given responsibilities.

    params:
    X = numpy.ndarray[numpy.ndarray[float]] - m x n
    r = numpy.ndarray[numpy.ndarray[float]] - k x m
    k = int

    returns:
    (new_MU, new_SIGMA, new_PI)
    new_MU = numpy.ndarray[numpy.ndarray[float]] - k x n
    new_SIGMA = numpy.ndarray[numpy.ndarray[numpy.ndarray[float]]] - k x n x n
    new_PI = numpy.ndarray[float] - k
    """
    # TODO: finish this function͏︅͏︀͏︋͏︋͏󠄌͏󠄎͏︀͏󠄐͏󠄃͏︃
    #raise NotImplementedError()
    m,n=X.shape
    newMU=np.zeros((k,n))
    newSIGMA=np.zeros((k,n,n))
    newPI=np.zeros(k)


    Nk=np.sum(r,axis=1)
    newPI=Nk/m

    for i in range(k):
        newMU[i]=(r[i]@X)/Nk[i]
    for i in range(k):
        ndiff=X-newMU[i]
        newSIGMA[i]=((r[i][:,None] * ndiff ).T @ ndiff)/Nk[i]

    return (newMU, newSIGMA, newPI)

