def best_segment(X,k,iters):
    """Determine the best segmentation
    of the image by repeatedly
    training the model and
    calculating its likelihood.
    Return the segment with the
    highest likelihood.

    params:
    X = numpy.ndarray[numpy.ndarray[float]] - m x n
    k = int
    iters = int

    returns:
    (likelihood, segment)
    likelihood = float
    segment = numpy.ndarray[numpy.ndarray[float]]
    """
    # TODO: finish this function͏︅͏︀͏︋͏︋͏󠄌͏󠄎͏︀͏󠄐͏󠄃͏︃
    #raise NotImplementedError()

    best_like=-np.inf
    best_seg=None

    for i in range(iters):
        MU,SIGMA,PI,r=train_model(X,k,default_convergence)
        like=likelihood(X, PI, MU, SIGMA, k)

        seg=segment(X, MU, k, r)

        if like >= best_like:
            best_like=like
            best_seg=seg
    return (best_like,best_seg)



