def new_convergence_function(previous_variables, new_variables, conv_ctr,
                             conv_ctr_cap=10):
    """
    Convergence function
    based on parameters:
    when all variables vary by
    less than 10% from the previous
    iteration's variables, increase
    the convergence counter.

    params:
    previous_variables = [numpy.ndarray[float]]
                         containing [means, variances, mixing_coefficients]
    new_variables = [numpy.ndarray[float]]
                    containing [means, variances, mixing_coefficients]
    conv_ctr = int
    conv_ctr_cap = int

    return:
    (conv_crt, converged)
    conv_ctr = int
    converged = boolean
    """

    mean_diff=np.allclose(previous_variables[0],new_variables[0],rtol=0.1)
    var_diff=np.allclose(previous_variables[1],new_variables[1],rtol=0.1)
    pi_diff=np.allclose(previous_variables[2],new_variables[2],rtol=0.1)

    converged=False

    if mean_diff and var_diff and pi_diff:
        conv_ctr+=1
    if conv_ctr==conv_ctr_cap:
        converged=True
    return (conv_ctr, converged)

