    while True:

        newMU, newSIGMA, newPI= M_step(X, responsibility, k)
        new_like=likelihood(X, newPI, newMU, newSIGMA, k)
        conv_ctr, conv_flag=new_convergence_function((MU,SIGMA,PI),(newMU, newSIGMA, newPI),conv_ctr)
        init_like=new_like

        if conv_flag:
            break
        responsibility=E_step(X,newMU,newSIGMA,newPI,k)
        MU,SIGMA,PI=(newMU,newSIGMA,newPI)

    return newMU, newSIGMA, newPI, responsibility

